INSERT INTO f10 VALUES
(336918,337158,$q$下面关于 BIOS 的说法中错误的是（）。$q$,$q$B$q$,$q$BIOS 主要包含 POST 程序、系统自举程序、CMOS 设置程序和基本外围设备的驱动程序，不是所有外围设备的驱动程序，故 B 错误。$q$,NULL,$q${"titleContent": "下面关于 BIOS 的说法中错误的是（）。", "analyze": "BIOS 主要包含 POST 程序、系统自举程序、CMOS 设置程序和基本外围设备的驱动程序，不是所有外围设备的驱动程序，故 B 错误。", "correct": null, "questionItemObjects": [{"prefix": "A", "content": "BIOS 是存放在主板 ROM 芯片中的一组机器语言程序", "itemUuid": "95e0e93e9db84fa8b56e5c2cc3209b0a", "score": null}, {"prefix": "B", "content": "BIOS 主要包含四个部分的程序:POST 程序、系统自举程序、CMOS 设置程序和所有外围设备的驱动程序", "itemUuid": "247b24c546e14c05abc9da3ff5452b62", "score": null}, {"prefix": "C", "content": "BIOS 具有启动计算机工作、诊断计算机故障及控制低级输入输出操作的功能", "itemUuid": "0a0de026ad514ad6ad2c698e81da490e", "score": null}, {"prefix": "D", "content": "不同的BIOS在PC机执行自举程序之前，规定用户启动CMOS设置程序的热键可能不同", "itemUuid": "49110630042841fa86aba6c0e190a4f6", "score": null}]}$q$),
(353288,353528,$q$移动互联网的特征不包括（）。$q$,$q$A$q$,$q$移动互联网具有便携性、交互性、多样性等特征，局限性不是其特征。故选 A。$q$,$q${"A": "局限性", "B": "交互性", "C": "便携性", "D": "多样性"}$q$,$q${"titleContent": "移动互联网的特征不包括（）。", "analyze": "移动互联网具有便携性、交互性、多样性等特征，局限性不是其特征。故选 A。", "correct": null, "questionItemObjects": [{"prefix": "A", "content": "局限性√", "itemUuid": "1461af5c67794fa2bc3e413fb182f766", "score": null}, {"prefix": "B", "content": "交互性√", "itemUuid": "1f0078607ff145bc8656b34894f6f000", "score": null}, {"prefix": "C", "content": "便携性", "itemUuid": "e793d775e21446d4b0673719acb91111", "score": null}, {"prefix": "D", "content": "多样性", "itemUuid": "cfd836e67ef94c42957e800c06a05560", "score": null}]}$q$),
(368359,368599,$q$启动 samba 服务器进程可以有两种方式：独立启动方式和父进程启动方式，其中后者是在（ ）文件中以独立进程方式启动。$q$,$q$D$q$,$q$父进程启动方式由 inetd 守护进程管理，配置在 /etc/inetd.conf 中。故选 D。$q$,NULL,$q${"titleContent": "启动 samba 服务器进程可以有两种方式：独立启动方式和父进程启动方式，其中后者是在（ ）文件中以独立进程方式启动。", "analyze": "父进程启动方式由 inetd 守护进程管理，配置在 /etc/inetd.conf 中。故选 D。", "correct": null, "questionItemObjects": [{"prefix": "A", "content": "/usr/sbin/smbd", "itemUuid": "bc8a691fa00f4e37a8f79d9c3bde355b", "score": null}, {"prefix": "B", "content": "/usr/sbin/nmbd", "itemUuid": "b4f4c7d75e304b668bcdc97a1c3da1dc", "score": null}, {"prefix": "C", "content": "rc. samba", "itemUuid": "5e4864da50154e0d94d95688aa69a069", "score": null}, {"prefix": "D", "content": "/etc/inetd.conf", "itemUuid": "ab5318177d734076b08c8830e86d0288", "score": null}]}$q$),
