(379870,380110,$q$双绞线由两根具有绝缘保护层的铜导线按一定密度互相绞在一起组成，这样可以降低信号干扰的程度。$q$,$q$A$q$,$q$双绞线由两根绝缘铜导线绞合而成，可降低信号干扰，说法正确。故选 A。$q$,NULL,$q${"titleContent": "双绞线由两根具有绝缘保护层的铜导线按一定密度互相绞在一起组成，这样可以降低信号干扰的程度。", "analyze": "双绞线由两根绝缘铜导线绞合而成，可降低信号干扰，说法正确。故选 A。", "correct": null, "questionItemObjects": [{"prefix": "A", "content": "对", "itemUuid": "1800b298db514d4dbce84b2418685a70", "score": null}, {"prefix": "B", "content": "错", "itemUuid": "b61cdf84b16c45638883f33de59b832d", "score": null}]}$q$),
(389515,389792,$q$在 PowerPoint 2003 中，既可编辑幻灯片又可编辑备注信息的是（）。$q$,$q$D$q$,$q$普通视图既可编辑幻灯片，也可编辑备注信息。故选 D。$q$,NULL,$q${"titleContent": "在 PowerPoint 2003 中，既可编辑幻灯片又可编辑备注信息的是（）。", "analyze": "普通视图既可编辑幻灯片，也可编辑备注信息。故选 D。", "correct": null, "questionItemObjects": [{"prefix": "A", "content": "备注页视图", "itemUuid": "c643a255876947609b3634a87986f2f6", "score": null}, {"prefix": "B", "content": "幻灯片浏览视图", "itemUuid": "97b75c65e8544bb9ae3e15f887632f0b", "score": null}, {"prefix": "C", "content": "幻灯片放映视图", "itemUuid": "ef265f580e4b457d983e681a09381a2f", "score": null}, {"prefix": "D", "content": "普通视图", "itemUuid": "58d691d76e0c48769f3665dcb4b74262", "score": null}]}$q$);
UPDATE t_question q SET stem=e.stem, correct=e.correct, analysis=e.analysis,
  option_json=coalesce(e.options,q.option_json), qc_grade='good', answer_check='match'
FROM f10 e WHERE q.id=e.id AND NOT q.is_golden;
UPDATE t_text_content t SET content=e.content FROM f10 e WHERE t.id=e.tc_id;
DO $$ DECLARE n int; BEGIN
 SELECT count(*) INTO n FROM t_question q JOIN f10 e ON e.id=q.id
  WHERE q.stem=e.stem AND q.correct=e.correct AND q.analysis=e.analysis
    AND q.qc_grade='good' AND q.answer_check='match'
    AND (e.options IS NULL OR q.option_json=e.options);
 IF n<>9 THEN RAISE EXCEPTION '更新应为9，实际%',n; END IF;
 SELECT count(*) INTO n FROM t_text_content t JOIN f10 e ON t.id=e.tc_id
  WHERE t.content=e.content AND pg_input_is_valid(t.content,'json');
 IF n<>9 THEN RAISE EXCEPTION '文本应为9，实际%',n; END IF;
 SELECT count(*) INTO n FROM practice_answer WHERE question_id IN (336918,353288,368359,370356,377027,378954,379702,379870,389515); IF n<>0 THEN RAISE EXCEPTION '有作答'; END IF;
 SELECT count(*) INTO n FROM t_question WHERE NOT deleted; IF n<>44419 THEN RAISE EXCEPTION '活跃数'; END IF;
 SELECT count(*) INTO n FROM t_question WHERE is_golden; IF n<>200 THEN RAISE EXCEPTION '金标数'; END IF;
END $$;
ROLLBACK;
